descriptor.templateCss:
.nav-header-widget {
  font-family: 'Open Sans', sans-serif;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: #fff;
  box-sizing: border-box;
  height: 100%;
  position: relative;
  overflow: visible !important;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex-shrink: 1;
}

.device-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: #333;
  min-width: 0;
  max-width: 40vw;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  white-space: normal;
  word-break: break-word;
  overflow-wrap: anywhere;
  line-height: 1.1;
}

.online-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
  display: inline-block;
  margin-right: 2px;
}
.online-dot.online { background: #4caf50; }
.online-dot.offline { background: #bdbdbd; }

/* ======= Desktop Nav (with text labels) ======= */
.desktop-nav {
  display: none;
  align-items: center;
  gap: 2px;
  flex-shrink: 1;
  min-width: 0;
  overflow-x: auto;
}
.nav-item {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 6px;
  cursor: pointer;
  color: #444;
  font-size: 12px;
  font-weight: 500;
  border-radius: 6px;
  transition: all 0.2s;
  white-space: nowrap;
}
.nav-item svg {
  flex-shrink: 0;
  fill: #555;
  transition: fill 0.2s;
}
.nav-item:hover {
  background: #f0f0f0;
  color: #222;
}
.nav-item:hover svg {
  fill: #333;
}
.nav-item.active {
  background: #e0e0e0;
  color: #333;
  font-weight: 600;
}
.nav-item.active svg {
  fill: #333;
}
.nav-divider {
  width: 1px;
  height: 20px;
  background: #ddd;
  margin: 0 2px;
  flex-shrink: 0;
}
.nav-item.no-label span {
  display: none;
}

/* ======= Mobile Nav (icon-only, right-aligned) ======= */
.mobile-nav {
  display: none;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}
.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  cursor: pointer;
  border-radius: 8px;
  transition: all 0.2s;
  -webkit-tap-highlight-color: rgba(0,0,0,0.08);
}
.icon-btn svg {
  fill: #555;
  transition: fill 0.2s;
}
.icon-btn:hover {
  background: #f0f0f0;
}
.icon-btn:hover svg {
  fill: #333;
}
.icon-btn:active {
  background: #e8e8e8;
}
.icon-btn.active {
  background: #e0e0e0;
}
.icon-btn.active svg {
  fill: #333;
}
.icon-divider {
  width: 1px;
  height: 20px;
  background: #ddd;
  margin: 0 1px;
  flex-shrink: 0;
}


/* ===== OTA Icon in Nav ===== */
.ota-nav-icon {
  position: relative;
  cursor: pointer;
}

/* ===== OTA Popup Overlay ===== */
.ota-popup-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0,0,0,0.4);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ota-popup {
  background: #fff;
  border-radius: 12px;
  width: 340px;
  max-width: 90vw;
  box-shadow: 0 8px 32px rgba(0,0,0,0.2);
  overflow: hidden;
  font-family: 'Open Sans', 'Segoe UI', sans-serif;
}
.ota-popup-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 18px;
  border-bottom: 1px solid #e0e0e0;
  background: #fff8e1;
}
.ota-popup-title {
  font-size: 15px;
  font-weight: 600;
  color: #333;
}
.ota-popup-close {
  font-size: 22px;
  color: #999;
  cursor: pointer;
  line-height: 1;
}
.ota-popup-close:hover { color: #333; }
.ota-popup-body {
  padding: 16px 18px;
}
.ota-info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid #f0f0f0;
}
.ota-info-row:last-of-type { border-bottom: none; }
.ota-info-label {
  font-size: 12px;
  color: #888;
  font-weight: 500;
}
.ota-info-value {
  font-size: 13px;
  color: #333;
  font-weight: 600;
}
.ota-new-ver { color: #e65100; }
.ota-precheck {
  font-size: 12px;
  color: #d32f2f;
  margin-top: 8px;
  min-height: 0;
}
.ota-progress { margin-top: 12px; }
.ota-progress-bar-container {
  background: #e0e0e0;
  border-radius: 4px;
  height: 8px;
  overflow: hidden;
}
.ota-progress-bar {
  background: #4caf50;
  height: 100%;
  transition: width 0.3s ease;
}
.ota-progress-text {
  font-size: 12px;
  color: #333;
  display: inline-block;
  margin-top: 4px;
}
.ota-status {
  margin-top: 8px;
  font-size: 12px;
  padding: 6px 10px;
  border-radius: 4px;
}
.ota-status.success { background: #e8f5e9; color: #2e7d32; }
.ota-status.error { background: #ffebee; color: #c62828; }
.ota-popup-footer {
  padding: 12px 18px 16px;
  text-align: center;
}
.ota-update-btn {
  background: #ff9800;
  color: white;
  border: none;
  border-radius: 6px;
  padding: 10px 28px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
}
.ota-update-btn:hover { background: #f57c00; }
.ota-update-btn:disabled { background: #ccc; cursor: not-allowed; }

descriptor.controllerScript:
var self = this;
var navDebounceTimer = null;
var isAdmin = false;
var otaWasActive = false;
var otaInitiated = false;
var otaValues = {};
var deviceIsActive = false;
var deviceIsOn = false;
var otaPopupEl = null;
var fwDescription = '';
var fwDownloadUrl = '';

self.onInit = function() {
    console.log('[NavHeader v9] === onInit ===');

    try {
        var el = self.ctx.$container[0];
        while (el && el !== document.body) {
            el.style.overflow = 'visible';
            el = el.parentElement;
        }
    } catch(e) {}

    detectAndApplyLayout();
    setupHandlers();
    loadDeviceInfo();
    highlightCurrentState();
    checkAdminAccess();
    setupOTAHandlers();

    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.data) {
        updateOnlineStatus(self.ctx.defaultSubscription.data);
    }
}

function detectAndApplyLayout() {
    var isMobile = true;
    try {
        var screenW = window.screen ? window.screen.width : 0;
        var mobileUA = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent || '');
        if (screenW > 0) { isMobile = (screenW < 769) || mobileUA; }
        else { isMobile = mobileUA; }
    } catch(e) { isMobile = true; }
    console.log('[NavHeader v9] isMobile=' + isMobile);

    var container = self.ctx.$container[0];
    if (!container) return;
    var desktopNav = container.querySelector('#desktopNav');
    var mobileNav = container.querySelector('#mobileNav');

    if (isMobile) {
        if (desktopNav) desktopNav.style.display = 'none';
        if (mobileNav) mobileNav.style.display = 'flex';
    } else {
        if (desktopNav) desktopNav.style.display = 'flex';
        if (mobileNav) mobileNav.style.display = 'none';
    }
}

// Immediately highlight the clicked item (don't wait for URL/state to update)
function highlightItem(targetState) {
    var container = self.ctx.$container[0];
    if (!container) return;
    var allItems = container.querySelectorAll('.nav-item, .icon-btn');
    for (var i = 0; i < allItems.length; i++) {
        var nav = allItems[i].getAttribute('data-navigate');
        if (nav === targetState) {
            allItems[i].classList.add('active');
        } else {
            allItems[i].classList.remove('active');
        }
    }
}

function highlightCurrentState() {
    var currentState = getCurrentState();
    if (!currentState) return;
    highlightItem(currentState);
}

function getCurrentState() {
    try {
        var url = new URL(window.location.href);
        var stateB64 = url.searchParams.get('state');
        if (!stateB64) {
            var hash = window.location.hash || '';
            var match = hash.match(/[?&]state=([^&]+)/);
            if (match) stateB64 = match[1];
        }
        if (stateB64) {
            var stateStr = decodeURIComponent(escape(atob(stateB64)));
            var stateArr = JSON.parse(stateStr);
            if (Array.isArray(stateArr) && stateArr.length > 0) {
                return stateArr[stateArr.length - 1].id;
            }
        }
    } catch(e) {}
    return null;
}

function setupHandlers() {
    var container = self.ctx.$container[0];
    if (!container) { console.error('[NavHeader v9] No container!'); return; }

    // Desktop nav items
    var desktopNav = container.querySelector('#desktopNav');
    if (desktopNav) {
        function handleDesktop(e) {
            var item = e.target.closest('.nav-item');
            if (!item) return;
            e.stopPropagation(); e.stopImmediatePropagation(); e.preventDefault();
            var action = item.getAttribute('data-action');
            if (action === 'openOTA') { openOTAPopup(); return; }
            var nav = item.getAttribute('data-navigate');
            if (nav) {
                // Immediately highlight, then debounce-navigate
                highlightItem(nav);
                debouncedNavigate(nav);
            }
        }
        desktopNav.addEventListener('touchstart', handleDesktop, true);
        desktopNav.addEventListener('mousedown', handleDesktop, true);
    }

    // Mobile icon-only nav items
    var mobileNav = container.querySelector('#mobileNav');
    if (mobileNav) {
        function handleMobile(e) {
            var item = e.target.closest('.icon-btn');
            if (!item) return;
            e.stopPropagation(); e.stopImmediatePropagation(); e.preventDefault();
            var action = item.getAttribute('data-action');
            if (action === 'openOTA') { openOTAPopup(); return; }
            var nav = item.getAttribute('data-navigate');
            if (nav) {
                // Immediately highlight, then debounce-navigate
                highlightItem(nav);
                debouncedNavigate(nav);
            }
        }
        mobileNav.addEventListener('touchstart', handleMobile, true);
        mobileNav.addEventListener('mousedown', handleMobile, true);
    }

    console.log('[NavHeader v9] Handlers attached');
}

// Debounce navigation so rapid clicks only fire the last one
function debouncedNavigate(targetState) {
    if (navDebounceTimer) { clearTimeout(navDebounceTimer); navDebounceTimer = null; }
    navDebounceTimer = setTimeout(function() {
        navDebounceTimer = null;
        navigateToState(targetState);
    }, 150);
}

function setDeviceName(name) {
    var el = self.ctx.$container.find('#deviceName');
    el.text(name || '');
    el.css('font-size', (name && String(name).length > 10) ? '0.78rem' : '');
}

function loadDeviceInfo() {
    getTargetEntity(function(entity) {
        if (!entity) return;
        self.ctx.attributeService.getEntityAttributes(entity, 'CLIENT_SCOPE', ['deviceName', '3Phase']).subscribe(function(attrs) {
            var found = false;
            var is3Phase = false;
            if (attrs) for (var i = 0; i < attrs.length; i++) {
                var k = attrs[i].key || attrs[i].attributeKey;
                if (k === 'deviceName' && attrs[i].value) {
                    setDeviceName(attrs[i].value);
                    found = true;
                }
                if (k === '3Phase') {
                    is3Phase = (attrs[i].value === true || attrs[i].value === 'true' || attrs[i].value === 1);
                }
            }
            if (!found) {
                loadDeviceLabelFallback(entity);
            }
            apply3PhaseVisibility(is3Phase);
        });
    });
}

function apply3PhaseVisibility(is3Phase) {
    var container = self.ctx.$container[0];
    if (!container) return;
    var energyItems = container.querySelectorAll('[data-navigate="monitoring_energy"]');
    for (var i = 0; i < energyItems.length; i++) {
        energyItems[i].style.display = is3Phase ? 'none' : '';
    }
}

function loadDeviceLabelFallback(entity) {
    if (!entity || !entity.id) { tryEntityNameFallback(); return; }
    var http = getHttpService();
    if (!http) { tryEntityNameFallback(); return; }
    http.get('/api/device/' + entity.id).subscribe(
        function(resp) {
            var device = resp.data || resp;
            if (device.label) setDeviceName(device.label);
            else if (device.name) setDeviceName(device.name);
            else tryEntityNameFallback();
        },
        function() { tryEntityNameFallback(); }
    );
}

function tryEntityNameFallback() {
    try {
        var ds = self.ctx.defaultSubscription.datasources[0];
        var name = ds.entityName || ds.entity.name || '';
        if (name) setDeviceName(name);
    } catch(e) {}
}

function getHttpService() {
    if (self.ctx.$injector) { try { return self.ctx.$injector.get('$http'); } catch(e) {} }
    if (self.ctx.http) return self.ctx.http;
    return null;
}

function updateOnlineStatus(data) {
    if (!data || !Array.isArray(data)) return;
    for (var i = 0; i < data.length; i++) {
        var item = data[i];
        if (item && item.dataKey && item.dataKey.name === 'active' && item.data) {
            var series = item.data;
            if (Array.isArray(series) && series.length > 0) {
                var last = series[series.length - 1];
                var val = Array.isArray(last) ? last[1] : last;
                var isActive = (val === true || val === 'true' || val === 1 || val === '1');
                deviceIsActive = isActive;
                var dotEl = self.ctx.$container.find('#onlineDot');
                if (isActive) { dotEl.attr('title', 'Online').removeClass('offline').addClass('online'); }
                else { dotEl.attr('title', 'Offline').removeClass('online').addClass('offline'); }
            }
        }
    }
}

// === Navigation ===
function navigateToState(targetState) {
    // Handle "Back to Device List" — navigate to default state (device list)
    if (targetState === 'back_to_list') {
        console.log('[NavHeader v9] Navigating back to device list');
        navigateBackToList();
        return;
    }

    var info = getEntityInfo();
    console.log('[NavHeader v9] Navigate to:', targetState, 'entity:', JSON.stringify(info));

    var sc = getStateController();
    if (sc) {
        try {
            if (typeof sc.openState === 'function') {
                var stateParams = {};
                if (info.entityId) stateParams.device_id = { entityId: info.entityId, entityName: info.entityName };
                sc.openState(targetState, stateParams, false);
                console.log('[NavHeader v9] Navigated via stateController.openState');
                return;
            }
        } catch(e) { console.warn('[NavHeader v9] stateController failed:', e); }
    }

    var descriptors = self.ctx.actionsApi && self.ctx.actionsApi.getActionDescriptors
        ? self.ctx.actionsApi.getActionDescriptors('headerClick') : [];
    if (descriptors && descriptors.length && info.entityId) {
        for (var i = 0; i < descriptors.length; i++) {
            if (descriptors[i].targetDashboardStateId === targetState) {
                self.ctx.actionsApi.handleWidgetAction({}, descriptors[i], info.entityId, info.entityName, null, null);
                return;
            }
        }
    }

    try {
        if (replaceStateInUrl(targetState, info)) {
            setTimeout(function() { window.location.reload(); }, 50);
            return;
        }
    } catch(e) {}

    if (descriptors && descriptors.length) {
        for (var j = 0; j < descriptors.length; j++) {
            if (descriptors[j].targetDashboardStateId === targetState) {
                self.ctx.actionsApi.handleWidgetAction({}, descriptors[j], null, null, null, null);
                return;
            }
        }
    }
    console.error('[NavHeader v9] Navigation failed for:', targetState);
}

function navigateBackToList() {
    // Method 1: stateController.resetState() or openState('default')
    var sc = getStateController();
    if (sc) {
        try {
            if (typeof sc.resetState === 'function') {
                sc.resetState();
                console.log('[NavHeader v9] Navigated back via stateController.resetState');
                return;
            }
        } catch(e) {}
        try {
            if (typeof sc.openState === 'function') {
                sc.openState('default', {}, false);
                console.log('[NavHeader v9] Navigated back via stateController.openState(default)');
                return;
            }
        } catch(e) {}
    }

    // Method 2: URL manipulation — reset state to default
    try {
        var url = new URL(window.location.href);
        var defaultState = [{ id: 'default', params: {} }];
        url.searchParams.set('state', btoa(unescape(encodeURIComponent(JSON.stringify(defaultState)))));
        window.history.replaceState(null, '', url.toString());
        setTimeout(function() { window.location.reload(); }, 50);
        return;
    } catch(e) {}

    // Method 3: window.history.back()
    try { window.history.back(); } catch(e) {}
}

function getEntityInfo() {
    var entityId = null, entityName = '';
    try {
        var subs = self.ctx.defaultSubscription;
        if (subs && subs.datasources && subs.datasources.length > 0) {
            var ds = subs.datasources[0];
            if (ds.entity && ds.entity.id) {
                var eid = ds.entity.id;
                entityId = (typeof eid === 'object') ? eid : { id: String(eid), entityType: 'DEVICE' };
                entityName = ds.entityName || ds.entity.name || '';
            }
        }
    } catch(e) {}
    if (!entityId) {
        try {
            var s = getUrlStateParam();
            if (s) { var a = JSON.parse(s); if (Array.isArray(a)) for (var i = a.length-1; i >= 0; i--) { if (a[i].params && a[i].params.device_id) { entityId = a[i].params.device_id.entityId; entityName = a[i].params.device_id.entityName || ''; break; } } }
        } catch(e) {}
    }
    return { entityId: entityId, entityName: entityName };
}

function replaceStateInUrl(targetState, info) {
    var stateStr = getUrlStateParam();
    var stateArr;
    if (!stateStr) {
        stateArr = [{ id: 'default', params: {} }];
    } else {
        try { stateArr = JSON.parse(stateStr); } catch(e) { return false; }
        if (!Array.isArray(stateArr) || !stateArr.length) stateArr = [{ id: 'default', params: {} }];
    }
    var dp = {};
    if (info.entityId) dp.entityId = info.entityId;
    if (info.entityName) dp.entityName = info.entityName;

    var lastId = stateArr[stateArr.length-1].id;
    var siblingStates = ['device_home','device_schedule','device_protection','monitoring_vc','monitoring_energy','monitoring_logs','device_monitoring','back_to_list'];
    var curIsSibling = siblingStates.indexOf(lastId) >= 0;
    var tgtIsSibling = siblingStates.indexOf(targetState) >= 0;
    if (lastId === 'default' || lastId === targetState || (curIsSibling && tgtIsSibling)) {
        stateArr[stateArr.length-1] = { id: targetState, params: { device_id: dp } };
    } else {
        stateArr.push({ id: targetState, params: { device_id: dp } });
    }

    var url = new URL(window.location.href);
    url.searchParams.set('state', btoa(unescape(encodeURIComponent(JSON.stringify(stateArr)))));
    window.history.replaceState(null, '', url.toString());
    return true;
}

function getUrlStateParam() {
    try {
        var url = new URL(window.location.href);
        var b = url.searchParams.get('state');
        if (!b) { var h = window.location.hash || ''; var m = h.match(/[?&]state=([^&]+)/); if (m) b = m[1]; }
        if (b) return decodeURIComponent(escape(atob(b)));
    } catch(e) {}
    return null;
}

function getStateController() {
    try { if (self.ctx.stateController) return self.ctx.stateController; } catch(e) {}
    try { if (self.ctx.dashboard && self.ctx.dashboard.stateController) return self.ctx.dashboard.stateController; } catch(e) {}
    try { if (self.ctx.dashboardCtx && self.ctx.dashboardCtx.stateController) return self.ctx.dashboardCtx.stateController; } catch(e) {}
    return null;
}

function getTargetEntity(cb) {
    var ds = self.ctx.defaultSubscription && self.ctx.defaultSubscription.datasources;
    if (ds && ds.length > 0) {
        var d = ds[0];
        if (d.entity && d.entity.id) { cb(normalizeEntity(d.entity)); return; }
        if (d.entityAliasId && self.ctx.aliasController) {
            var ai = self.ctx.aliasController.getInstantAliasInfo(d.entityAliasId);
            if (ai && ai.currentEntity) { cb(normalizeEntity(ai.currentEntity)); return; }
            if (ai && ai.resolvedEntities && ai.resolvedEntities.length > 0) { cb(normalizeEntity(ai.resolvedEntities[0])); return; }
        }
    }
    cb(null);
}

function normalizeEntity(e) {
    if (!e) return null;
    var id = e.id, et = e.entityType;
    if (typeof id === 'object' && id !== null) { et = et || id.entityType; id = id.id !== undefined ? id.id : id; }
    if (!id) return null;
    return { id: String(id), entityType: et || 'DEVICE' };
}

self.onDataUpdated = function() {
    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.data) {
        updateOnlineStatus(self.ctx.defaultSubscription.data);
        updateOTAFromData(self.ctx.defaultSubscription.data);
    }
}

// ===== OTA Functions =====
function checkAdminAccess() {
    var http = getHttpService();
    if (!http) return;
    http.get('/api/auth/user').subscribe(
        function(resp) {
            var user = resp.data || resp;
            isAdmin = (user.authority === 'TENANT_ADMIN');
            console.log('[NavHeader] Admin check: ' + isAdmin + ', authority: ' + user.authority);
            updateOTAIcon();
        },
        function() { isAdmin = false; }
    );
}

function setupOTAHandlers() {
    var container = self.ctx.$container;
    container.find('#otaIconDesktop, #otaIconMobile').on('click touchstart', function(e) {
        e.stopPropagation();
        e.preventDefault();
        openOTAPopup();
    });

    // Create popup on document.body so it is not clipped by widget overflow
    createOTAPopup();
}

function createOTAPopup() {
    if (otaPopupEl) return;
    var popupHtml = '<div class="ota-popup-overlay" id="otaPopupOverlay" style="display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.4);z-index:999999;display:none;align-items:center;justify-content:center;">'
        + '<div style="background:#fff;border-radius:12px;width:340px;max-width:90vw;box-shadow:0 8px 32px rgba(0,0,0,0.2);overflow:hidden;font-family:Open Sans,Segoe UI,sans-serif;">'
        + '<div id="otaPopupHeaderDiv" style="display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid #e0e0e0;background:#fff8e1;">'
        + '<span id="otaPopupTitle" style="font-size:15px;font-weight:600;color:#333;">Firmware Update Available</span>'
        + '<span id="otaPopupClose" style="font-size:22px;color:#999;cursor:pointer;line-height:1;">&times;</span>'
        + '</div>'
        + '<div style="padding:16px 18px;">'
        + '<p id="otaDescParagraph" style="font-size:12.5px;color:#555;line-height:1.5;margin:0 0 12px 0;"></p>'
