        + '<div id="otaPreCheck" style="font-size:12px;color:#d32f2f;margin-top:8px;"></div>'
        + '</div>'
        + '<div id="otaProgress" style="display:none;margin-top:12px;"><div style="background:#e0e0e0;border-radius:4px;height:8px;overflow:hidden;"><div id="otaProgressBar" style="background:#4caf50;height:100%;width:0%;transition:width 0.3s ease;"></div></div><span id="otaProgressText" style="font-size:12px;color:#333;display:inline-block;margin-top:4px;">0%</span></div>'
        + '<div id="otaStatus" style="display:none;margin-top:8px;font-size:12px;padding:6px 10px;border-radius:4px;"><span id="otaStatusText"></span></div>'
        + '</div>'
        + '<div style="padding:12px 18px 16px;text-align:center;"><button id="otaUpdateBtn" style="background:#ff9800;color:white;border:none;border-radius:6px;padding:10px 28px;font-size:13px;font-weight:600;cursor:pointer;width:100%;">Update Firmware</button></div>'
        + '</div></div>';
    otaPopupEl = $(popupHtml);
    $('body').append(otaPopupEl);

    otaPopupEl.find('#otaPopupClose').on('click', function() { closeOTAPopup(); });
    otaPopupEl.on('click', function(e) {
        if ($(e.target).is(otaPopupEl)) closeOTAPopup();
    });
    otaPopupEl.find('#otaUpdateBtn').on('click', function(e) {
        e.preventDefault();
        handleOTAUpdate();
    });

}

function updateOTAFromData(data) {
    if (!data || !Array.isArray(data)) return;
    for (var i = 0; i < data.length; i++) {
        var item = data[i];
        if (!item || !item.dataKey || !item.data) continue;
        var key = item.dataKey.name;
        var series = item.data;
        if (Array.isArray(series) && series.length > 0) {
            var last = series[series.length - 1];
            var val = Array.isArray(last) ? last[1] : last;
            otaValues[key] = val;
        }
    }
    // Track relay state from telemetry
    if (otaValues.relayStatus !== undefined) {
        deviceIsOn = (otaValues.relayStatus === 1 || otaValues.relayStatus === '1' || otaValues.relayStatus === true || otaValues.relayStatus === 'true');
    }
    updateOTAIcon();
    updateOTAPopup();
}

// Cloud OTA is only reliable from v1.18.0 onwards. Builds before that pin the GoDaddy G2
// root CA for the firmware download, so the HTTPS GET fails once the server certificate is
// issued by another CA (Let's Encrypt) and the device reports fw_state=FAILED. startOTA RPC
// itself exists from v1.14.0, which is why older devices accept the command and then error.
var MIN_CLOUD_OTA = [1, 18, 0];

// true only when the device reported a version and it is >= MIN_CLOUD_OTA
function cloudOtaSupported() {
    var v = otaValues.firmwareVersion;
    if (v === undefined || v === null || String(v) === '') return false;
    var parts = String(v).replace(/^[^0-9]*/, '').split('.');
    var dev = [parseInt(parts[0] || '0', 10), parseInt(parts[1] || '0', 10), parseInt(parts[2] || '0', 10)];
    for (var i = 0; i < 3; i++) {
        if (isNaN(dev[i])) return false;
        if (dev[i] !== MIN_CLOUD_OTA[i]) return dev[i] > MIN_CLOUD_OTA[i];
    }
    return true;
}

function minCloudOtaText() {
    return 'v' + MIN_CLOUD_OTA.join('.');
}

function updateOTAIcon() {
    var fwAvailable = (otaValues.fw_update_available === true || otaValues.fw_update_available === 'true');
    // If device explicitly reports fw_update_available as false, respect it (e.g. manual firmware upload via embedded server)
    var fwExplicitlyFalse = (otaValues.fw_update_available === false || otaValues.fw_update_available === 'false');
    // For legacy devices (< 1.13.5) that don't publish fw_update_available, fall back to target_fw_version
    if (!fwAvailable && !fwExplicitlyFalse && otaValues.target_fw_version && otaValues.target_fw_version !== '') fwAvailable = true;
    // If current version matches target version, device is already up to date — hide icon
    if (fwAvailable && otaValues.firmwareVersion && otaValues.target_fw_version) {
        var curV = (otaValues.firmwareVersion || '').replace(/^[^0-9]*/, '').split(/[\s-]/)[0];
        if (curV === otaValues.target_fw_version) fwAvailable = false;
    }
    // Old devices with no firmware info but firmware IS assigned to profile (fw_title exists)
    if (!fwAvailable && !otaValues.fw_update_available && !otaValues.target_fw_version && otaValues.fw_title) {
        fwAvailable = true;
    }
    // Do not advertise an update the device cannot actually install: no version reported,
    // or a build older than MIN_CLOUD_OTA. An OTA already in flight is still shown below.
    if (!cloudOtaSupported()) fwAvailable = false;
    var fwState = otaValues.fw_state || 'IDLE';
    var showIcon = fwAvailable || (fwState === 'DOWNLOADING' || fwState === 'UPDATING' || fwState === 'UPDATED' || otaInitiated || otaWasActive);

    self.ctx.$container.find('#otaIconDesktop').css('display', showIcon ? 'flex' : 'none');
    self.ctx.$container.find('#otaIconMobile').css('display', showIcon ? 'flex' : 'none');
}

function openOTAPopup() {
    if (!otaPopupEl) createOTAPopup();
    otaPopupEl.css('display', 'flex');
    updateOTAPopup();
    fetchFirmwareDescription();

}

function closeOTAPopup() {
    if (otaPopupEl) otaPopupEl.hide();
}

function updateOTAPopup() {
    var overlay = otaPopupEl;
    if (!overlay.is(':visible')) return;

    var fwAvailable = (otaValues.fw_update_available === true || otaValues.fw_update_available === 'true');
    var fwExplicitlyFalse = (otaValues.fw_update_available === false || otaValues.fw_update_available === 'false');
    if (!fwAvailable && !fwExplicitlyFalse && otaValues.target_fw_version && otaValues.target_fw_version !== '') fwAvailable = true;
    var targetVer = otaValues.target_fw_version || '';
    var currentVer = otaValues.firmwareVersion || '';
    var fwState = otaValues.fw_state || 'IDLE';
    var fwProgress = parseInt(otaValues.fw_progress || 0, 10);
    var fwTitle = otaValues.fw_title || '';

    otaPopupEl.find('#otaFwTitle').text(fwTitle || '-');
    otaPopupEl.find('#otaTargetVersion').text(targetVer ? 'v' + targetVer : '-');
    otaPopupEl.find('#otaCurrentVersion').text(currentVer || '-');
    if (fwDescription) {
        otaPopupEl.find('#otaFwDescription').text(fwDescription);
        otaPopupEl.find('#otaDescRow').show();
    }

    // Update description paragraph
    var descTarget = targetVer ? 'v' + targetVer : '';
    var descText = 'There is a new firmware available for your SuperSmart device.';
    if (descTarget) {
        descText += ' Do you like to update to firmware version <strong>' + descTarget + '</strong>? Please note, the device will restart after the update.';
    }

    otaPopupEl.find('#otaDescParagraph').html(descText);

    // Cloud OTA needs a known firmware version at or above MIN_CLOUD_OTA
    var canCloudOTA = cloudOtaSupported();

    if (!canCloudOTA) {
        otaPopupEl.find('#otaManualMsg').html('Your device firmware ' + (currentVer ? '(' + currentVer + ') ' : '') + 'is below ' + minCloudOtaText() + ' and does not support cloud OTA updates. Please contact <strong>EVIQtech support</strong> for assistance with updating the device firmware.');
        otaPopupEl.find('#otaManualUpdateInfo').show();
        otaPopupEl.find('#otaInfoTable').hide();
        otaPopupEl.find('#otaUpdateBtn').hide();
        return;
    } else {
        otaPopupEl.find('#otaManualUpdateInfo').hide();
        otaPopupEl.find('#otaInfoTable').show();
        otaPopupEl.find('#otaUpdateBtn').show();
    }

    var btn = otaPopupEl.find('#otaUpdateBtn');
    var progressDiv = otaPopupEl.find('#otaProgress');
    var statusDiv = otaPopupEl.find('#otaStatus');
    var precheck = otaPopupEl.find('#otaPreCheck');

    // Check if current version matches target — device is already up to date
    if (currentVer && targetVer && fwState !== 'DOWNLOADING' && fwState !== 'UPDATING' && !otaInitiated && !otaWasActive) {
        var curV = currentVer.replace(/^[^0-9]*/, '').split(/[\s-]/)[0];
        if (curV === targetVer) {
            otaPopupEl.find('#otaPopupTitle').text('Firmware Information');
            otaPopupEl.find('#otaPopupHeaderDiv').css('background', '#e8f5e9');
            otaPopupEl.find('#otaDescParagraph').html('Your device is already updated with the latest firmware version <strong>v' + targetVer + '</strong>.');
            btn.hide();
            progressDiv.hide();
            precheck.empty();
            showOTAStatus('Device firmware is up to date.', 'success');
            return;
        }
    }

    // Reset popup header to default state
    otaPopupEl.find('#otaPopupTitle').text('Firmware Update Available');
    otaPopupEl.find('#otaPopupHeaderDiv').css('background', '#fff8e1');
    btn.show();

    // Track OTA activity
    if (fwState === 'DOWNLOADING' || fwState === 'UPDATING' || fwState === 'UPDATED') {
        otaWasActive = true;
    }

    // Handle post-OTA: update complete, waiting for device to restart with new firmware
    if (otaWasActive && fwState !== 'DOWNLOADING' && fwState !== 'UPDATING') {
        if (!fwAvailable) {
            // Device restarted with new firmware — success
            otaWasActive = false;
            otaInitiated = false;
            closeOTAPopup();
            updateOTAIcon();
            return;
        }
        if (fwState === 'UPDATED') {
            // OTA flashed successfully, device about to restart
            btn.prop('disabled', false).text('Close');
            progressDiv.hide();
            precheck.empty();
            showOTAStatus('Firmware update complete. Device is restarting...', 'success');
            return;
        }
        if (fwState === 'FAILED') {
            otaWasActive = false;
            otaInitiated = false;
            btn.prop('disabled', false).text('Retry Update');
            progressDiv.hide();
            precheck.empty();
            showOTAStatus('Firmware update failed. Please try again.', 'error');
            return;
        }
        // fwState is IDLE — device restarted but fwAvailable still true
        if (deviceIsActive) {
            // Check if firmware versions match — update was successful
            var curV = (otaValues.firmwareVersion || '').replace(/^[^0-9]*/, '').split(/[\s-]/)[0];
            var tgtV = (otaValues.target_fw_version || '');
            if (curV && tgtV && curV === tgtV) {
                btn.prop('disabled', false).text('Close');
                progressDiv.hide();
                precheck.empty();
                showOTAStatus('Firmware updated successfully to v' + tgtV + '!', 'success');
                return;
            }
            otaWasActive = false;
        } else {
            // Device still restarting
            btn.prop('disabled', true).text('Restarting...');
            progressDiv.hide();
            precheck.empty();
            showOTAStatus('Firmware update complete. Device is restarting...', 'success');
            return;
        }
    }

    precheck.empty();
    if (fwState === 'DOWNLOADING' || fwState === 'UPDATING') {
        otaInitiated = false;
        btn.prop('disabled', true).text('Updating... ' + fwProgress + '%');
        progressDiv.show();
        otaPopupEl.find('#otaProgressBar').css('width', fwProgress + '%');
        otaPopupEl.find('#otaProgressText').text(fwProgress + '%');
        statusDiv.hide();
    } else if (fwState === 'FAILED') {
        otaWasActive = false;
        otaInitiated = false;
        btn.prop('disabled', false).text('Retry Update');
        progressDiv.hide();
        showOTAStatus('Firmware update failed. Please try again.', 'error');
    } else if (otaInitiated) {
        btn.prop('disabled', true).text('Waiting for device...');
        progressDiv.hide();
        statusDiv.hide();
    } else {
        btn.prop('disabled', false).text('Update Firmware');
        progressDiv.hide();
        statusDiv.hide();
        // Pre-checks
        if (!deviceIsActive) {
            precheck.text('Device is offline. Cannot update firmware.');
            btn.prop('disabled', true);
        } else if (deviceIsOn) {
            precheck.text('Device is ON. Please turn off before updating.');
            btn.prop('disabled', true);
        }
    }
}

function showOTAStatus(message, type) {
    var statusDiv = otaPopupEl.find('#otaStatus');
    statusDiv.removeClass('success error').addClass(type);
    otaPopupEl.find('#otaStatusText').text(message);
    statusDiv.show();
}

function handleOTAUpdate() {
    // If update already completed, close popup
    var curState = otaValues.fw_state || 'IDLE';
    if (curState === 'UPDATED' || (otaWasActive && curState === 'IDLE' && deviceIsActive)) {
        otaWasActive = false;
        otaInitiated = false;
        closeOTAPopup();
        updateOTAIcon();
        return;
    }
    if (!deviceIsActive) { showOTAStatus('Device is offline.', 'error'); return; }
    if (deviceIsOn) { showOTAStatus('Turn off the device before updating firmware.', 'error'); return; }

    var targetVer = otaPopupEl.find('#otaTargetVersion').text();
    if (!confirm('Update firmware to ' + targetVer + '?\nThe device will restart after the update.')) return;

    getTargetEntity(function(entity) {
        if (!entity || !entity.id) { showOTAStatus('Device not found.', 'error'); return; }
        var http = getHttpService();
        if (!http) { showOTAStatus('HTTP service unavailable.', 'error'); return; }

        otaPopupEl.find('#otaUpdateBtn').prop('disabled', true).text('Initiating...');
        otaPopupEl.find('#otaStatus').hide();

        http.post('/api/rpc/oneway/' + entity.id, {method: 'startOTA', params: {}, timeout: 10000}).subscribe(
            function() {
                otaInitiated = true;
                otaPopupEl.find('#otaUpdateBtn').text('Waiting for device...');
                updateOTAIcon();
            },
            function(err) {
                showOTAStatus('Failed to send update command.', 'error');
                otaPopupEl.find('#otaUpdateBtn').prop('disabled', false).text('Update Firmware');
            }
        );
    });
}


function fetchFirmwareDescription() {
    if (!isAdmin) return;
    var http = getHttpService();
    if (!http) return;

    getTargetEntity(function(entity) {
        if (!entity || !entity.id) return;
        // Get device to find firmwareId
        http.get('/api/device/' + entity.id).subscribe(
            function(resp) {
                var device = resp.data || resp;
                var fwId = null;
                if (device.firmwareId && device.firmwareId.id) {
                    fwId = device.firmwareId.id;
                }
                if (!fwId && device.deviceProfileId && device.deviceProfileId.id) {
                    // Check device profile for firmware assignment
                    http.get('/api/deviceProfile/' + device.deviceProfileId.id).subscribe(
                        function(profileResp) {
                            var profile = profileResp.data || profileResp;
                            if (profile.firmwareId && profile.firmwareId.id) {
                                loadFwDescription(profile.firmwareId.id);
                            }
                        },
                        function() {}
                    );
                    return;
                }
                if (fwId) loadFwDescription(fwId);
            },
            function() {}
        );
    });
}

function loadFwDescription(fwId) {
    var http = getHttpService();
    if (!http || !fwId) return;
    http.get('/api/otaPackage/info/' + fwId).subscribe(
        function(resp) {
            var fw = resp.data || resp;
            var desc = '';
            if (fw.additionalInfo && fw.additionalInfo.description) {
                desc = fw.additionalInfo.description;
            }
            fwDescription = desc;
            if (otaPopupEl) {
                if (desc) {
                    otaPopupEl.find('#otaFwDescription').text(desc);
                    otaPopupEl.find('#otaDescRow').show();
                } else {
                    otaPopupEl.find('#otaDescRow').hide();
                }
                // Store firmware ID for programmatic download
                if (fwId) {
                    otaPopupEl.data('fwId', fwId);
                }
            }
        },
        function() {}
    );
}

function fetchDownloadUrl() {
    getTargetEntity(function(entity) {
        if (!entity || !entity.id) return;
        var entId = { entityType: 'DEVICE', id: entity.id };
        self.ctx.attributeService.getEntityAttributes(entId, 'SHARED_SCOPE', ['fw_download_url']).subscribe(function(attrs) {
            if (attrs) {
                for (var i = 0; i < attrs.length; i++) {
                    var k = attrs[i].key || attrs[i].attributeKey;
                    if (k === 'fw_download_url' && attrs[i].value) {
                        fwDownloadUrl = attrs[i].value;
                        console.log('[NavHeader] fw_download_url: ' + fwDownloadUrl);
                    }
                }
            }
        });
    });
}

function handleFirmwareDownload() {
    // If external download URL available, open it directly (works for customers too)
    if (fwDownloadUrl) {
        window.open(fwDownloadUrl, '_blank');
        return;
    }
    // Otherwise use ThingsBoard API (admin only)
    var fwId = otaPopupEl ? otaPopupEl.data('fwId') : null;
    if (!fwId) {
        showOTAStatus('Firmware package not found.', 'error');
        return;
    }
    var http = getHttpService();
    if (!http) {
        showOTAStatus('HTTP service unavailable.', 'error');
        return;
    }

    var btn = otaPopupEl.find('#otaDownloadBtn');
    btn.prop('disabled', true).text('Downloading...');

    http.get('/api/otaPackage/info/' + fwId).subscribe(
        function(resp) {
            var fw = resp.data || resp;
            var fileName = (fw.fileName || fw.title || 'firmware') + '.bin';
            // Download the binary with auth headers
            http({
                method: 'GET',
                url: '/api/otaPackage/' + fwId + '/download',
                responseType: 'arraybuffer'
            }).then(
                function(dlResp) {
                    var blob = new Blob([dlResp.data], {type: 'application/octet-stream'});
                    var url = window.URL.createObjectURL(blob);
                    var a = document.createElement('a');
                    a.href = url;
                    a.download = fileName;
                    document.body.appendChild(a);
                    a.click();
                    document.body.removeChild(a);
                    window.URL.revokeObjectURL(url);
                    btn.prop('disabled', false).text('Download Firmware');
                },
                function() {
                    btn.prop('disabled', false).text('Download Firmware');
                    showOTAStatus('Download failed.', 'error');
                }
            );
        },
        function() {
            btn.prop('disabled', false).text('Download Firmware');
            showOTAStatus('Could not get firmware info.', 'error');
        }
    );
}

self.onDestroy = function() {
    if (navDebounceTimer) { clearTimeout(navDebounceTimer); navDebounceTimer = null; }
    if (otaPopupEl) { otaPopupEl.remove(); otaPopupEl = null; }
}
